"""The synthetic spreadsheet fixture system (build plan 6H.1, 6H.2, 6H.8).

Every dataset ForgeXL's automated tests process is **built here, in memory,
from Python literals**. The repository contains no `.csv` or `.xlsx` blob, no
company spreadsheet and no file that had to be saved by hand from Excel — a
rule build plan 6H.8 states and `test_spreadsheet_fixtures.py` asserts.

Two shapes are enough for everything the build plan's fixture list needs:

    Table      one dataset: a header plus rows. Renders as CSV *or* as a
               one-worksheet workbook, so the same fixture proves that both
               upload paths reach the same result.
    Workbook   named worksheets in order. The cases that are *about* workbook
               structure — several data sheets, a workbook holding nothing —
               cannot be expressed as a single table.

Determinism is the property that makes any of this evidence (build plan 6H.1).
Nothing here reads a clock, a random source, an environment variable or the
filesystem, so a fixture's bytes are a pure function of its literals and
`as_csv()` returns the identical bytes on every call, on every machine, in
every process. :func:`large_table` is generated by arithmetic on the row index
for the same reason.

Two writer settings matter and are not defaults:

* ``strings_to_formulas=False`` — xlsxwriter otherwise turns any cell whose
  text begins with ``=`` into a *formula*. A fixture builder that silently
  converts text into something else cannot be used to prove the application
  never does (build plan section 16). This is the same setting
  `app.services.export` applies for the same reason.
* ``in_memory=True`` — xlsxwriter otherwise spools workbook parts through the
  OS temporary directory. A fixture system for a runtime that writes nothing
  should not itself write files (build plan 6F.2).
"""

from __future__ import annotations

import csv
import io
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Any

import xlsxwriter

#: The worksheet a single-table fixture is written to when nothing else is
#: asked for. Named for what it holds rather than for Excel's "Sheet1".
DEFAULT_WORKSHEET = "Data"

CSV_EXTENSION = ".csv"
XLSX_EXTENSION = ".xlsx"

#: The two upload formats every `Table` can be rendered as. Tests parametrise
#: over this so a fixture is never proved in one format only.
UPLOAD_EXTENSIONS: tuple[str, ...] = (CSV_EXTENSION, XLSX_EXTENSION)

#: Options every fixture workbook is written with. See the module docstring:
#: neither is xlsxwriter's default and both are deliberate.
_WORKBOOK_OPTIONS: dict[str, object] = {
    "in_memory": True,
    "strings_to_formulas": False,
}

#: Rows of a worksheet, header included; ``None`` is a blank cell.
Rows = tuple[tuple[Any, ...], ...]


def _write_workbook(sheets: Sequence[tuple[str, Rows]]) -> bytes:
    """Render named worksheets to workbook bytes.

    A `None` cell is skipped rather than written, which is what leaves a
    genuinely blank cell in the file — writing an empty string would store a
    string, and the two are different things to both Excel and the parser.
    """
    buffer = io.BytesIO()
    workbook = xlsxwriter.Workbook(buffer, _WORKBOOK_OPTIONS)
    for name, rows in sheets:
        worksheet = workbook.add_worksheet(name)
        for row_index, row in enumerate(rows):
            for column_index, value in enumerate(row):
                if value is not None:
                    worksheet.write(row_index, column_index, value)
    workbook.close()
    return buffer.getvalue()


@dataclass(frozen=True)
class Table:
    """One synthetic dataset, renderable as either upload format.

    `name` identifies the fixture in test IDs; `description` says what the
    dataset is *for*, so a failure names the scenario rather than a row index.
    """

    name: str
    description: str
    header: tuple[str, ...]
    rows: Rows

    @property
    def row_count(self) -> int:
        return len(self.rows)

    @property
    def column_count(self) -> int:
        return len(self.header)

    def as_csv(self) -> bytes:
        """Render as CSV bytes.

        `None` becomes an empty field, which is how a CSV expresses a blank
        cell. Line endings are fixed at ``\\n`` so the bytes do not depend on
        the platform the suite runs on.
        """
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(self.header)
        writer.writerows(
            ["" if value is None else value for value in row] for row in self.rows
        )
        return buffer.getvalue().encode("utf-8")

    def as_xlsx(self, *, worksheet: str = DEFAULT_WORKSHEET) -> bytes:
        """Render as a workbook holding this table on one worksheet."""
        return _write_workbook([(worksheet, (self.header, *self.rows))])

    def payload(self, extension: str) -> bytes:
        """Render in whichever upload format `extension` names."""
        if extension == CSV_EXTENSION:
            return self.as_csv()
        if extension == XLSX_EXTENSION:
            return self.as_xlsx()
        raise ValueError(f"No fixture renderer for {extension!r}.")

    def filename(self, extension: str) -> str:
        """A plausible upload filename for this fixture."""
        return f"{self.name}{extension}"

    def with_columns(self, *columns: str) -> "Table":
        """This table narrowed to `columns`, in the order given.

        Used to state an expected output by *construction* — "the Product
        Master is these six columns of the upload, deduplicated" — rather than
        by copying values into a second literal that could drift from the
        first.
        """
        indexes = [self.header.index(name) for name in columns]
        return Table(
            name=f"{self.name}-{'-'.join(columns).lower()}",
            description=f"{self.description} (narrowed to {', '.join(columns)})",
            header=tuple(columns),
            rows=tuple(tuple(row[index] for index in indexes) for row in self.rows),
        )

    def deduplicated(self) -> "Table":
        """This table with exactly-repeated rows dropped, first kept.

        The expected output of the Exact Duplicate Remover, computed here from
        the fixture's own literals with plain Python — deliberately *not* by
        calling Polars or the Action, so a test comparing the two is comparing
        two independent implementations rather than one against itself.
        """
        seen: set[tuple[Any, ...]] = set()
        kept: list[tuple[Any, ...]] = []
        for row in self.rows:
            if row not in seen:
                seen.add(row)
                kept.append(row)
        return Table(
            name=f"{self.name}-deduplicated",
            description=f"{self.description} (exact duplicates removed)",
            header=self.header,
            rows=tuple(kept),
        )


@dataclass(frozen=True)
class Workbook:
    """A synthetic workbook with named worksheets, in order.

    For the fixture scenarios that are about a workbook's *structure* rather
    than about a dataset: several plausible data sheets, or none at all.
    """

    name: str
    description: str
    sheets: tuple[tuple[str, Rows], ...]

    @property
    def sheet_names(self) -> tuple[str, ...]:
        return tuple(name for name, _ in self.sheets)

    def as_xlsx(self) -> bytes:
        return _write_workbook(self.sheets)

    def filename(self) -> str:
        return f"{self.name}{XLSX_EXTENSION}"


