# ---------------------------------------------------------------------------
# The larger dataset (build plan 6H.2)
# ---------------------------------------------------------------------------

#: Distinct product combinations :func:`large_table` cycles through.
#:
#: Every column of the generated row is a function of ``index % PRODUCT_POOL``,
#: so two rows are identical exactly when their indexes are congruent modulo
#: this number. That makes both proof Actions' expected output computable
#: without deduplicating anything: a table of `n` rows holds
#: ``min(n, PRODUCT_POOL)`` distinct rows, and they appear in generation order.
PRODUCT_POOL = 250

#: Values cycled through the generated columns. Coprime lengths against
#: `PRODUCT_POOL` are not needed — the SKU alone makes each pool entry
#: distinct — but varying them keeps the data from looking like one repeated
#: row with a changing ID.
_SUPPLIERS = ("Acme Imports", "Vinco", "Global Cellars")
_PRODUCERS = ("Château Margaux", "Bodegas Muñoz", "Domaine Père et Fils", "Weingut Löwen")
_SELECTIONS = ("Réserve", "Estate", "Añejo", "Grand Cru", None)
_VOLUMES = ("750ml", "1.5L", "375ml")

#: Column names of a generated large table — the Product Master Builder's six
#: required columns plus one it must drop, so one fixture drives both Actions.
LARGE_TABLE_HEADER: tuple[str, ...] = (
    "SKU",
    "Vintage",
    "Supplier",
    "Producer",
    "Selection",
    "Volume",
    "Units",
)


def large_table(row_count: int, *, name: str | None = None) -> Table:
    """Generate a deterministic dataset of `row_count` rows.

    Build plan 6H.2 asks for a larger fixture, and 6H.1 for fixtures that are
    generated rather than stored. Generating this one keeps a multi-megabyte
    blob out of the repository entirely, at the cost of building it per run —
    the trade the project takes, because a stored fixture is a second artifact
    that can drift from the code that reads it.

    Every value derives from ``index % PRODUCT_POOL`` by arithmetic alone, so
    the result depends on nothing but `row_count`: no clock, no random source,
    no platform detail. Two rows are identical exactly when their indexes are
    congruent modulo :data:`PRODUCT_POOL`, which is what makes both Actions'
    expected output a closed-form number rather than something a test has to
    deduplicate for itself.

    Args:
        row_count: Rows to generate. Zero produces a header-only table.
        name: Fixture name; defaults to one naming the size.
    """
    if row_count < 0:
        raise ValueError("row_count may not be negative.")

    rows = tuple(_large_row(index) for index in range(row_count))
    return Table(
        name=name or f"large-{row_count}",
        description=(
            f"{row_count:,} generated rows cycling through {PRODUCT_POOL} "
            "distinct products."
        ),
        header=LARGE_TABLE_HEADER,
        rows=rows,
    )


def _large_row(index: int) -> tuple[Any, ...]:
    """One generated row, a pure function of `index`."""
    product = index % PRODUCT_POOL
    return (
        f"SKU-{product:05d}",
        2000 + (product % 25),
        _SUPPLIERS[product % len(_SUPPLIERS)],
        _PRODUCERS[product % len(_PRODUCERS)],
        _SELECTIONS[product % len(_SELECTIONS)],
        _VOLUMES[product % len(_VOLUMES)],
        product % 97,
    )


def distinct_rows_in_large_table(row_count: int) -> int:
    """Rows a `large_table(row_count)` holds once duplicates are removed."""
    return min(row_count, PRODUCT_POOL)